"use client";

import { useState } from "react";
import { 
  Wallet, ArrowUpRight, ArrowDownLeft, 
  Search, TrendingUp, DollarSign, Calendar,
  Plus, X, Upload, Save, FileText
} from "lucide-react";

// DATA DUMMY
const initialTransactions = [
  { id: 1, title: "Dana Sponsorship Telkomsel", category: "Sponsorship", date: "2026-01-02", type: "income", amount: 2500000, pic: "Raka (Ketua)" },
  { id: 2, title: "Belanja ATK Rapat Pleno", category: "Operasional", date: "2026-01-03", type: "expense", amount: 150000, pic: "Siti (Sekretaris)" },
  { id: 3, title: "Iuran Kas Kelas X RPL 1", category: "Kas Wajib", date: "2026-01-04", type: "income", amount: 300000, pic: "Bendahara 1" },
  { id: 4, title: "Konsumsi Tamu Pemateri", category: "Konsumsi", date: "2026-01-05", type: "expense", amount: 450000, pic: "Seksi Acara" },
  { id: 5, title: "Cetak Banner Event", category: "Perlengkapan", date: "2026-01-05", type: "expense", amount: 120000, pic: "Seksi Pubdok" },
];

export default function KasPage() {
  const [transactions, setTransactions] = useState(initialTransactions);
  const [filterType, setFilterType] = useState('all'); 
  const [isModalOpen, setIsModalOpen] = useState(false);

  // FORM STATE
  const [formData, setFormData] = useState({
    title: "",
    amount: "",
    type: "expense",
    category: "Operasional",
    date: new Date().toISOString().split('T')[0],
    pic: ""
  });

  const totalIncome = transactions.filter(t => t.type === 'income').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = transactions.filter(t => t.type === 'expense').reduce((acc, curr) => acc + curr.amount, 0);
  const currentBalance = totalIncome - totalExpense;

  const formatRupiah = (num: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(num);

  const filteredData = filterType === 'all' ? transactions : transactions.filter(t => t.type === filterType);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTx = {
      id: Date.now(),
      title: formData.title,
      category: formData.category,
      date: formData.date,
      type: formData.type,
      amount: Number(formData.amount),
      pic: formData.pic || "Admin"
    };
    setTransactions([newTx, ...transactions]);
    setIsModalOpen(false);
    setFormData({ title: "", amount: "", type: "expense", category: "Operasional", date: new Date().toISOString().split('T')[0], pic: "" });
  };

  return (
    <div className="h-[calc(100vh-6rem)] flex flex-col xl:flex-row gap-6 font-sans relative">
      
      {/* === MODAL POPUP (FIXED OVERLAY & INPUT COLORS) === */}
      {isModalOpen && (
        // Menggunakan 'fixed' bukan 'absolute' agar menutupi seluruh layar browser, bukan cuma container
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
           <div className="bg-white dark:bg-[#1e293b] w-full max-w-md rounded-2xl shadow-2xl border border-slate-200 dark:border-white/10 overflow-hidden animate-in zoom-in-95 duration-200 relative">
              
              {/* Modal Header */}
              <div className="px-6 py-4 border-b border-slate-100 dark:border-white/5 flex justify-between items-center bg-slate-50 dark:bg-white/5">
                 <h3 className="font-black text-slate-800 dark:text-white flex items-center gap-2">
                    <Plus size={18} className="text-blue-600"/> Catat Transaksi Baru
                 </h3>
                 <button onClick={() => setIsModalOpen(false)} className="p-1 hover:bg-slate-200 dark:hover:bg-white/10 rounded-full transition-colors text-slate-500 dark:text-slate-400"><X size={18}/></button>
              </div>

              {/* Modal Form */}
              <form onSubmit={handleSubmit} className="p-6 space-y-4">
                 
                 {/* Toggle Type */}
                 <div className="grid grid-cols-2 gap-2 p-1 bg-slate-100 dark:bg-slate-800/50 rounded-xl border border-transparent dark:border-white/5">
                    <button type="button" onClick={() => setFormData({...formData, type: 'income'})} className={`py-2 rounded-lg text-xs font-black transition-all flex items-center justify-center gap-2 ${formData.type === 'income' ? 'bg-green-500 text-white shadow-md' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-white/5'}`}>
                       <ArrowUpRight size={14}/> Pemasukan
                    </button>
                    <button type="button" onClick={() => setFormData({...formData, type: 'expense'})} className={`py-2 rounded-lg text-xs font-black transition-all flex items-center justify-center gap-2 ${formData.type === 'expense' ? 'bg-red-500 text-white shadow-md' : 'text-slate-500 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-white/5'}`}>
                       <ArrowDownLeft size={14}/> Pengeluaran
                    </button>
                 </div>

                 <div className="space-y-3">
                    <div>
                       <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">Judul Transaksi</label>
                       {/* FIX: Input color di dark mode */}
                       <input required type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} 
                          className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 dark:text-white placeholder-slate-400" 
                          placeholder="Contoh: Beli Kertas A4" 
                       />
                    </div>
                    
                    <div className="grid grid-cols-2 gap-3">
                       <div>
                          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">Nominal (Rp)</label>
                          <input required type="number" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} 
                             className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 dark:text-white placeholder-slate-400" 
                             placeholder="0" 
                          />
                       </div>
                       <div>
                          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">Kategori</label>
                          <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} 
                             className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 dark:text-white"
                          >
                             <option>Operasional</option>
                             <option>Konsumsi</option>
                             <option>Sponsorship</option>
                             <option>Kas Wajib</option>
                             <option>Perlengkapan</option>
                          </select>
                       </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                       <div>
                          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">Tanggal</label>
                          <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} 
                             className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 dark:text-white dark:[color-scheme:dark]" 
                          />
                       </div>
                       <div>
                          <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">PIC</label>
                          <input type="text" value={formData.pic} onChange={e => setFormData({...formData, pic: e.target.value})} 
                             className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 dark:text-white placeholder-slate-400" 
                             placeholder="Nama..." 
                          />
                       </div>
                    </div>

                    <div>
                       <label className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">Bukti Transaksi</label>
                       <div className="w-full h-16 border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-lg flex flex-col items-center justify-center text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer">
                          <Upload size={16}/>
                          <span className="text-[9px] font-bold mt-1">Upload Struk/Nota</span>
                       </div>
                    </div>
                 </div>

                 <button type="submit" className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-600/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                    <Save size={16}/> Simpan Transaksi
                 </button>

              </form>
           </div>
        </div>
      )}

      {/* === LEFT PANEL: DASHBOARD === */}
      <div className="w-full xl:w-[400px] flex flex-col gap-6 shrink-0 h-full overflow-y-auto custom-scrollbar pr-1">
         {/* Main Card */}
         <div className="bg-gradient-to-br from-slate-900 via-[#0f172a] to-slate-800 p-6 rounded-2xl text-white shadow-2xl relative overflow-hidden border border-slate-700">
            <div className="absolute top-0 right-0 w-40 h-40 bg-blue-500/20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
            <div className="absolute bottom-0 left-0 w-32 h-32 bg-purple-500/20 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2"></div>
            <div className="relative z-10">
               <div className="flex justify-between items-start mb-8">
                  <div className="p-2 bg-white/10 backdrop-blur-md rounded-lg border border-white/10"><Wallet size={24} className="text-blue-400" /></div>
                  <span className="text-[10px] font-bold uppercase tracking-widest bg-white/10 px-2 py-1 rounded text-slate-300">OSKA Finance</span>
               </div>
               <p className="text-slate-400 text-xs font-medium mb-1">Total Saldo Aktif</p>
               <h1 className="text-4xl font-bold font-black tracking-tight mb-6">{formatRupiah(currentBalance)}</h1>
               <div className="grid grid-cols-2 gap-4">
                  <div className="bg-white/5 p-3 rounded-xl border border-white/5"><p className="text-sm font-bold text-green-400">{formatRupiah(totalIncome)}</p></div>
                  <div className="bg-white/5 p-3 rounded-xl border border-white/5"><p className="text-sm font-bold text-red-400">{formatRupiah(totalExpense)}</p></div>
               </div>
            </div>
         </div>

         {/* Quick Actions */}
         <div className="grid grid-cols-2 gap-4">
            <button onClick={() => setIsModalOpen(true)} className="p-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow-lg shadow-blue-600/20 flex flex-col items-center justify-center gap-2 transition-all active:scale-95 group">
               <div className="p-2 bg-white/20 rounded-full group-hover:rotate-90 transition-transform"><Plus size={20}/></div>
               <span className="text-xs font-bold">Catat Transaksi</span>
            </button>
            <button className="p-4 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 text-slate-700 dark:text-slate-300 rounded-xl shadow-sm hover:shadow-md flex flex-col items-center justify-center gap-2 transition-all active:scale-95">
               <div className="p-2 bg-slate-100 dark:bg-white/10 rounded-full"><FileText size={20}/></div>
               <span className="text-xs font-bold">Laporan PDF</span>
            </button>
         </div>

         {/* Mini Stats */}
         <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
            <h3 className="text-xs font-bold font-black text-slate-800 dark:text-white uppercase tracking-wide mb-4 flex items-center gap-2"><TrendingUp size={16} className="text-blue-500"/> Financial Health</h3>
            <div className="space-y-4">
               <div>
                  <div className="flex justify-between text-[10px] font-bold mb-1"><span className="text-slate-500 dark:text-slate-400">Budget Terpakai</span><span className="text-slate-800 dark:text-white">{Math.round((totalExpense / totalIncome) * 100)}%</span></div>
                  <div className="h-2 w-full bg-slate-100 dark:bg-white/10 rounded-full overflow-hidden">
                     <div className="h-full bg-gradient-to-r from-blue-500 to-purple-500 rounded-full" style={{ width: `${(totalExpense / totalIncome) * 100}%` }}></div>
                  </div>
               </div>
               <p className="text-[10px] text-slate-400">Kondisi keuangan <span className="text-green-500 font-bold">Sehat</span>.</p>
            </div>
         </div>
      </div>

      {/* === RIGHT PANEL: HISTORY === */}
      <div className="flex-1 bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col overflow-hidden">
         <div className="p-5 border-b border-slate-100 dark:border-white/5 flex justify-between items-center bg-slate-50/50 dark:bg-white/5">
            <div><h2 className="text-sm font-bold font-black text-slate-800 dark:text-white uppercase tracking-wide">Riwayat Transaksi</h2><p className="text-[10px] text-slate-500">Real-time update</p></div>
            <div className="flex gap-2">
                <div className="flex bg-white dark:bg-[#1e293b] rounded-lg border border-slate-200 dark:border-white/10 p-1">
                  {['all', 'income', 'expense'].map(type => (
                    <button key={type} onClick={() => setFilterType(type)} className={`px-3 py-1.5 rounded-md text-[10px] font-bold capitalize transition-all ${filterType === type ? 'bg-slate-100 dark:bg-white/20 text-blue-600 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-300'}`}>{type === 'all' ? 'Semua' : type === 'income' ? 'Masuk' : 'Keluar'}</button>
                  ))}
                </div>
                <div className="relative"><input type="text" placeholder="Cari..." className="pl-8 pr-3 py-2 bg-white dark:bg-[#1e293b] border border-slate-200 dark:border-white/10 rounded-lg text-xs outline-none focus:ring-2 focus:ring-blue-500 w-32 text-slate-900 dark:text-white placeholder-slate-400" /><Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" /></div>
            </div>
         </div>

         <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
            <table className="w-full text-left border-collapse">
               <thead className="bg-slate-50 dark:bg-white/5 sticky top-0 z-10">
                  <tr>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider rounded-l-xl">Transaksi</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider">Kategori</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider">Tanggal</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider text-right rounded-r-xl">Jumlah</th>
                  </tr>
               </thead>
               <tbody className="text-xs">
                  {filteredData.map((t) => (
                     <tr key={t.id} className="border-b border-slate-50 dark:border-white/5 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors">
                        <td className="p-4">
                           <div className="flex items-center gap-3">
                              <div className={`p-2 rounded-full ${t.type === 'income' ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400' : 'bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400'}`}>
                                 {t.type === 'income' ? <ArrowUpRight size={16}/> : <ArrowDownLeft size={16}/>}
                              </div>
                              <div>
                                 <span className="font-bold text-slate-700 dark:text-slate-200 block">{t.title}</span>
                                 <span className="text-[10px] text-slate-400">{t.pic}</span>
                              </div>
                           </div>
                        </td>
                        <td className="p-4"><span className="px-2 py-1 rounded-md bg-slate-100 dark:bg-white/10 text-[10px] font-bold text-slate-500 dark:text-slate-400">{t.category}</span></td>
                        <td className="p-4 text-slate-500 dark:text-slate-400 font-medium"><div className="flex items-center gap-1.5"><Calendar size={12}/> {t.date}</div></td>
                        <td className={`p-4 text-right font-black ${t.type === 'income' ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                           {t.type === 'income' ? '+' : '-'} {formatRupiah(t.amount)}
                        </td>
                     </tr>
                  ))}
               </tbody>
            </table>
            {filteredData.length === 0 && <div className="flex flex-col items-center justify-center py-20 text-slate-400 opacity-50"><DollarSign size={48} className="mb-2"/><p className="text-sm font-bold">Data tidak ditemukan</p></div>}
         </div>
      </div>
    </div>
  );
}